    if not command.strip() or "\x00" in command:
        return None, "The command is empty or contains an invalid null character."
    if any(token in command for token in ("\n", "\r", "|", ";", "&", ">", "<", "`", "$")):
        return ["/bin/sh", "-c", command], None
